// Shape of GET /templates/work-packages (generated by tools/extract_templates.py from the .docx templates).

export interface TemplateRequirement {
  id: string;
  text: string;
}

export interface TemplateAppendix {
  letter: string;
  summary: string;
  canonical: string;
}

export interface WorkPackageTemplate {
  code: string; // T1..T8
  short: string; // WAN, MDF, CAB, LAN, ITH, OTH, OTM, OTN
  name: string; // package name used in the title
  sourceFile: string;
  scope: Partial<Record<"objective" | "coverage" | "standards" | "clarifications" | "exclusions", string>>;
  functionalRequirements: TemplateRequirement[];
  technicalRequirements: TemplateRequirement[];
  appendices: TemplateAppendix[];
  bomSections: string[];
}

export interface CanonicalAppendix {
  letter: string;
  number: string;
  title: string;
}

export interface DeliverableRow {
  milestoneKey: string;
  milestone: string;
  phase: string;
  items: string[];
}

export interface TemplateLibrary {
  version: string;
  templates: WorkPackageTemplate[];
  canonicalAppendix: CanonicalAppendix[];
  deliverables: DeliverableRow[];
  combinedStandards: string;
  combinedStandardsT8Suffix: string;
}

export interface MilestonePlanTemplate {
  source: string;
  phases: string[];
  milestones: { key: string; name: string }[];
  activities: unknown[];
}

